def can_chain(dominoes):
    if not dominoes:
        return []

    def solve(current_chain, remaining_dominoes):
        if not remaining_dominoes:
            # All dominoes used. Check if the first and last ends of the chain match.
            if current_chain[0][0] == current_chain[-1][1]:
                return current_chain
            else:
                return None

        last_val_in_chain = current_chain[-1][1]

        for i in range(len(remaining_dominoes)):
            domino = remaining_dominoes[i]

            # Create a new list for remaining_dominoes by removing the current one.
            # This correctly handles duplicate dominoes as distinct items.
            new_remaining = remaining_dominoes[:i] + remaining_dominoes[i+1:]

            # Try to append the domino in its original orientation [domino[0], domino[1]]
            if domino[0] == last_val_in_chain:
                result = solve(current_chain + [domino], new_remaining)
                if result is not None:
                    return result

            # Try to append the domino in its flipped orientation [domino[1], domino[0]]
            # This is only a distinct option if domino[0] != domino[1].
            # If domino is a double ([X,X]), the first 'if' branch covers both orientations
            # as they are identical. Trying it again would be redundant.
            if domino[0] != domino[1] and domino[1] == last_val_in_chain:
                flipped_domino = [domino[1], domino[0]]
                result = solve(current_chain + [flipped_domino], new_remaining)
                if result is not None:
                    return result

        return None # No solution found from this path

    # Try each domino as the starting piece, in both orientations
    for i in range(len(dominoes)):
        first_domino = dominoes[i]

        # Prepare the list of remaining dominoes for the recursive call
        remaining_after_first = dominoes[:i] + dominoes[i+1:]

        # Try with first_domino in its original orientation
        result = solve([first_domino], remaining_after_first)
        if result is not None:
            return result

