        # Only if the domino is not a double, otherwise the starting piece is identical.
        if first_domino[0] != first_domino[1]:
            flipped_first_domino = [first_domino[1], first_domino[0]]
            result = solve([flipped_first_domino], remaining_after_first)
            if result is not None:
                return result

    return None # No chain found at all
